  ('111', '45', 'Fleece-Lined', 'girths-fleece-lined', 'Soft Against the Skin', 'Girths lined with fleece, for thin skin and for horses in hard work.', 'Fleece-Lined Girths', 'Girths lined with fleece, for thin skin and for horses in hard work. In stock at Tack Rack, Ngong Road, Nairobi.', NULL, '3', '1', '2026-10-13 19:00:38', '2026-10-13 19:00:38'),
  ('112', '45', 'Elastic', 'girths-elastic', 'Give at the Buckle', 'Girths with elastic ends, so the horse can fill its chest without the girth fighting it.', 'Elastic Girths', 'Girths with elastic ends, so a horse can fill its chest without the girth fighting it. From Tack Rack, Nairobi.', NULL, '4', '1', '2026-10-13 19:00:38', '2026-10-13 19:00:38'),
  ('113', '48', 'Brushing Boots', 'brushing-boots', 'Pony, Cob & Full', 'Boots with a moulded strike guard, protecting the inside of the leg from the opposite hoof.', 'Brushing Boots', 'Boots with a moulded strike guard, protecting the inside of the leg from the opposite hoof. Pony, cob and full at Tack Rack, Nairobi.', NULL, '1', '1', '2026-10-13 19:00:38', '2026-10-13 19:00:38'),
  ('114', '48', 'Overreach Boots', 'overreach-boots', 'Neoprene & Rubber', 'Neoprene and rubber overreach boots, guarding the heel and coronet from a hind foot.', 'Overreach Boots', 'Neoprene and rubber overreach boots guarding the heel and coronet from a hind foot. Pony, cob and full. From Tack Rack, Nairobi.', NULL, '2', '1', '2026-10-13 19:00:38', '2026-10-13 19:00:38'),
  ('115', '48', 'Bandages', 'bandages', 'Fleece, Cohesive & Pads', 'Exercise and stable bandages with the quilted pads that go underneath them.', 'Bandages & Pads', 'Exercise and stable bandages with the quilted pads that go underneath them. In stock at Tack Rack, Ngong Road, Nairobi.', NULL, '3', '1', '2026-10-13 19:00:38', '2026-10-13 19:00:38'),
  ('116', '56', 'Body Brushes', 'body-brushes', 'For the Shine', 'Soft-bristled brushes used with a curry comb to lift dust and bring up a coat.', 'Horse Brushes', 'Body brushes for the shine, dandy brushes for the mud, and brushes for mane and tail. From Tack Rack, Ngong Road, Nairobi.', NULL, '1', '1', '2026-10-13 19:00:38', '2026-10-13 19:00:38'),
  ('117', '56', 'Dandy Brushes', 'dandy-brushes', 'For the Mud', 'Stiff-bristled brushes for dried mud and sweat, used before the body brush.', 'Dandy Brushes', 'Stiff-bristled brushes for dried mud and sweat, used before the body brush. In stock at Tack Rack, Ngong Road, Nairobi.', NULL, '2', '1', '2026-10-13 19:00:38', '2026-10-13 19:00:38'),
  ('118', '56', 'Mane & Tail Brushes', 'mane-tail-brushes', 'Without Pulling', 'Brushes that work through a mane and tail without tearing the hair out.', 'Mane & Tail Brushes', 'Brushes that work through a mane and tail without tearing the hair out. In stock at Tack Rack, Ngong Road, Nairobi.', NULL, '3', '1', '2026-10-13 19:00:38', '2026-10-13 19:00:38'),
  ('119', '45', 'Dressage', 'dressage-girths', 'Short, 22\" to 30\"', 'Short girths for a dressage saddle, 22 to 30 inches, so the buckles sit clear of the leg.', 'Short Dressage Girths', 'Short girths for a dressage saddle, 22 to 30 inches, in brown and black. In stock at Tack Rack, Ngong Road, Nairobi.', NULL, '1', '1', '2026-10-13 19:07:12', '2026-10-13 19:07:12'),
  ('120', '2', 'Numnahs & Saddle Pads', 'numnahs-saddle-pads', 'Shaped, Square & Non-Slip', 'Shaped GP numnahs, dressage squares, non-slip and Prolite pads, and fleece blankets.', 'Numnahs, Saddlepads & Blankets', 'Shaped GP numnahs, dressage squares, non-slip and Prolite pads and fleece blankets. Stocked at Tack Rack, Ngong Road, Nairobi.', NULL, '6', '1', '2026-10-13 19:55:09', '2026-10-13 19:55:09');
