INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name`, `slug`, `sku`, `short_desc`, `description`, `specifications`, `sizing_guide`, `price`, `price_visible`, `buyable`, `stock_status`, `stock_qty`, `is_featured`, `is_new`, `is_active`, `views`, `sort_order`, `meta_title`, `meta_desc`, `created_at`, `updated_at`) VALUES
  ('1880', '92', '6', 'Thorowgood Saddle', 'thorowgood-saddle', NULL, 'A soft-leather English saddle with a deep, comfortable seat.', 'An English saddle in soft black leather, cut for riders who school, jump and hack the same horse. The seat is deep enough to feel secure over a fence without locking the rider out of a flatwork position, and the panels are shaped to sit close to the horse.\n\nThorowgood saddles are known for being forgiving to fit and kind on the horse\'s back. As with every saddle we supply, this one is fitted on the horse before it leaves us.', 'Leather: soft-grain black\nSeat: padded\nGullet: interchangeable\nPanels: shaped for close contact\nMaker: Thorowgood\nFitting: included, on the horse', 'Seat size is taken from the rider, gullet and panel from the horse. Book a fitting before ordering — we travel to yards across Kenya.', NULL, '0', '0', 'in_stock', NULL, '1', '0', '1', '0', '0', 'Thorowgood Leather Saddle', 'A soft-leather English saddle with a deep, comfortable seat, fitted on your horse by our Society of Master Saddlers qualified fitter.', '2026-10-13 19:55:09', '2026-10-13 19:55:09'),
  ('1881', '90', '7', 'Wintec Synthetic Saddle', 'wintec-synthetic-saddle', NULL, 'A hard-wearing synthetic saddle with a grippy suede-effect seat.', 'A synthetic saddle built for riders who want low maintenance without giving up fit. The suede-effect seat gives real grip, and the whole saddle can be washed down after a dusty ride rather than needing oiling.\n\nSynthetic saddles suit the Kenyan climate particularly well — they do not dry out and crack the way leather can at altitude.', 'Material: synthetic with suede-effect seat\nGullet: interchangeable\nCare: wipe or wash clean, no oiling\nMaker: Wintec\nFitting: included, on the horse', 'Fitted on the horse. Wintec gullets are adjustable, which makes them a sensible choice for a young or changing horse.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Wintec Synthetic Saddle', 'A washable synthetic saddle with a grippy seat — low maintenance and well suited to the Kenyan climate. Fitted on the horse in Nairobi.', '2026-10-13 19:55:35', '2026-10-13 19:55:35'),
  ('1882', '91', '8', 'Jeffries Elite Leather Saddle', 'jeffries-elite-leather-saddle', NULL, 'A havana brown English saddle, hand finished, with the Elite embossing.', 'A traditional English saddle in rich havana brown leather from Jeffries, one of the long-standing Walsall saddlery names. The Elite model is hand finished, with a warm, deep colour that comes up beautifully with regular feeding.\n\nA saddle of this quality is a long-term purchase. It is worth having it fitted properly and re-checked as the horse changes shape.', 'Leather: havana brown, hand finished\nModel: Elite, embossed on the flap\nGullet: interchangeable\nMaker: Jeffries Saddlery, England\nFittings: stainless steel\nFitting: included, on the horse', 'Seat size from the rider, gullet and panel from the horse. We recommend a fitting before purchase and an annual re-check.', NULL, '0', '0', 'in_stock', NULL, '1', '0', '1', '0', '0', 'Jeffries Elite Leather Saddle', 'A hand-finished havana brown English saddle with the Elite embossing. Fitted on your horse at Tack Rack, Ngong Road, Nairobi.', '2026-10-13 19:55:39', '2026-10-13 19:55:39'),
  ('1883', '41', NULL, 'Black Leather General Purpose Saddle', 'black-leather-general-purpose-saddle', NULL, 'A classic black leather GP saddle with a padded seat.', 'A straightforward black leather general purpose saddle — the saddle most riders in Kenya end up using day to day. Comfortable enough for a long hack, secure enough for a lesson and a small course.\n\nFitted on the horse before it leaves the shop.', 'Leather: black\nSeat: padded general purpose\nFittings: stainless steel\nFitting: included, on the horse', 'Seat size from the rider, gullet and panel from the horse.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Black Leather GP Saddle', 'A classic black leather general purpose saddle with a padded seat — one saddle for flatwork, hacking and jumping. Fitted in Nairobi.', '2026-10-13 19:55:48', '2026-10-13 19:55:48'),
  ('1884', '90', '7', 'Wintec 2000 All Purpose Saddle', 'wintec-2000-all-purpose-saddle', NULL, 'The Wintec 2000 — adjustable, washable and genuinely low maintenance.', 'The Wintec 2000 is an all purpose synthetic saddle with an adjustable gullet, so the same saddle can be re-fitted as a horse changes shape or moved between horses of similar build. It washes clean, does not dry out, and weighs noticeably less than a leather equivalent.\n\nA sensible first saddle, and a practical choice for a busy yard.', 'Material: synthetic, washable\nGullet: adjustable (EASY-CHANGE system)\nSeat: all purpose\nMaker: Wintec\nFitting: included, on the horse', 'The adjustable gullet is changed to suit the horse at fitting. Seat size is taken from the rider.', NULL, '0', '0', 'in_stock', NULL, '1', '0', '1', '0', '0', 'Wintec 2000 All Purpose Saddle', 'An adjustable gullet and a washable synthetic hide — change the fit as your horse changes shape. In stock at Tack Rack, Nairobi.', '2026-10-13 19:55:57', '2026-10-13 19:55:57'),
  ('1885', '88', NULL, 'Black Skull Cap', 'black-skull-cap', NULL, 'A plain black skull cap, the standard for cross country and racing.', 'A classic skull cap shape with no fixed peak, so a silk can be fitted over it. This is the hat of choice for cross country, racing work and anyone who wants maximum coverage at the back of the head.\n\nAlways buy a hat that has been fitted to your head. A hat that moves is a hat that will not do its job.', 'Shell: hard, textured finish\nShape: skull cap, no fixed peak\nSilk: fits a standard hat silk (sold separately)', 'Measure around the head just above the ears. Come in and be fitted if you possibly can — head shapes differ as much as sizes.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Black Skull Cap', 'A plain black skull cap for cross country and racing, worn under a silk. Fitted in person at Tack Rack, Ngong Road, Nairobi.', '2026-10-13 19:56:08', '2026-10-13 19:56:08'),
  ('1886', '87', '9', 'HKM Velvet Riding Hat', 'hkm-velvet-riding-hat', NULL, 'A traditional black velvet riding hat with a fixed peak.', 'The traditional show hat: black velvet finish with a fixed peak and a neat, low profile. Correct turnout for the show ring, Pony Club and everyday schooling.\n\nSupplied by HKM.', 'Finish: black velvet\nPeak: fixed\nHarness: adjustable\nMaker: HKM', 'Measure around the head just above the ears, and have it fitted before you ride in it.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'HKM Velvet Riding Hat', 'A traditional black velvet riding hat with a fixed peak, correct for the show ring. Fitted in person at Tack Rack, Nairobi.', '2026-10-13 19:56:13', '2026-10-13 19:56:13'),
  ('1887', '87', NULL, 'Matt Black Vented Riding Helmet', 'matt-black-vented-riding-helmet', NULL, 'A modern low-profile helmet with front venting, in matt black.', 'A modern riding helmet with a low, clean profile and front vents that make a real difference schooling in the sun. The matt black finish is understated and does not show dust the way a gloss shell does.\n\nA good everyday helmet for schooling, hacking and lessons.', 'Shell: matt black, low profile\nVentilation: front vents\nPeak: short moulded peak\nHarness: adjustable retention system', 'Measure around the head just above the ears. We fit every helmet we sell — bring your head, not just a tape measure.', NULL, '0', '0', 'in_stock', NULL, '1', '0', '1', '0', '0', 'Matt Black Vented Riding Helmet', 'A low-profile vented helmet in matt black — cool to ride in and smart enough to compete in. Fitted in person in Nairobi.', '2026-10-13 19:56:18', '2026-10-13 19:56:18'),
  ('1888', '89', '10', 'USG Body Protector — BETA 2018 Level 3', 'usg-body-protector-beta-2018-level-3', NULL, 'Certified BETA 2018 Level 3 body protection, the standard for cross country.', 'A body protector certified to BETA 2018 Level 3 — the level required for cross country and the level we would recommend to any rider jumping at speed. Segmented foam panels flex with the body so it does not fight you in the saddle.\n\nA body protector must fit closely to work. Come in and be measured; the fit matters far more than the brand.', 'Certification: BETA 2018 Level 3\nConstruction: segmented foam panels\nAdjustment: shoulder, chest and waist\nMaker: USG', 'Measured across the chest, waist and back length. A body protector that is too big is worse than none at all — always be fitted.', NULL, '0', '0', 'in_stock', NULL, '1', '0', '1', '0', '0', 'USG Body Protector, BETA Level 3', 'Certified BETA 2018 Level 3 body protection — the standard required for cross country. Fitted in person at Tack Rack, Nairobi.', '2026-10-13 19:56:24', '2026-10-13 19:56:24'),
  ('1889', '89', '11', 'Whitaker Body Protector', 'whitaker-body-protector', NULL, 'A close-fitting body protector with a full-length front zip.', 'A body protector from Whitaker with a full-length front zip and a mesh back panel for airflow. The zip makes it far easier to get in and out of than a pull-over design, particularly for younger riders.\n\nFitted at the shop — the protection only works if it sits correctly on the body.', 'Closure: full-length front zip\nBack: ventilated mesh panel\nAdjustment: shoulder and waist straps\nMaker: Whitaker', 'Measured across the chest, waist and back length. Please be fitted rather than ordering by guess.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Whitaker Body Protector', 'A close-fitting body protector with a full-length front zip. Sized and fitted in person at Tack Rack, Ngong Road, Nairobi.', '2026-10-13 19:56:34', '2026-10-13 19:56:34'),
  ('1890', '93', NULL, 'Black Leather Snaffle Bridle', 'black-leather-snaffle-bridle', NULL, 'A complete black leather snaffle bridle with reins.', 'A full black leather snaffle bridle supplied with reins — headpiece, browband, cheekpieces, cavesson noseband and throatlash. Stainless steel fittings throughout.\n\nGood leather, kept fed, will outlast several cheaper bridles. In this climate a monthly balm is the difference between a bridle that lasts a decade and one that cracks in a season.', 'Leather: black\nFittings: stainless steel\nIncludes: headpiece, browband, cheekpieces, noseband, throatlash and reins\nNoseband: cavesson', 'Available in pony, cob and full. Cob fits the majority of horses in Kenya. Measure from the corner of the mouth over the poll and back.', NULL, '0', '0', 'in_stock', NULL, '1', '0', '1', '0', '0', 'Black Leather Snaffle Bridle', 'A complete black leather snaffle bridle supplied with reins — everyday tack that smartens up for the ring. From Tack Rack, Nairobi.', '2026-10-13 19:56:38', '2026-10-13 19:56:38'),
  ('1891', '93', NULL, 'Havana Leather Snaffle Bridle', 'havana-leather-snaffle-bridle', NULL, 'The same bridle in warm havana brown leather.', 'A complete snaffle bridle in havana brown leather with stainless steel fittings. Brown tack suits a bay or chestnut particularly well and is correct for hunting and most showing classes.\n\nSupplied with matching reins.', 'Leather: havana brown\nFittings: stainless steel\nIncludes: headpiece, browband, cheekpieces, noseband, throatlash and reins\nNoseband: cavesson', 'Available in pony, cob and full. Measure from the corner of the mouth over the poll and back.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Havana Leather Snaffle Bridle', 'The same leather snaffle bridle in warm havana brown, supplied with reins. Stocked in full and cob sizes at Tack Rack, Nairobi.', '2026-10-13 19:56:45', '2026-10-13 19:56:45'),
  ('1892', '95', '12', 'Shires Loose Ring Snaffle with Copper Lozenge', 'shires-loose-ring-snaffle-with-copper-lozenge', NULL, 'A double-jointed loose ring snaffle with a copper lozenge centre.', 'A loose ring snaffle with a double joint and a copper lozenge in the centre. The double joint removes the nutcracker action of a single-jointed bit, and the copper encourages the horse to salivate and soften.\n\nA fair, mild bit and a sensible first choice for a young horse.', 'Material: stainless steel with copper lozenge\nMouthpiece: double jointed\nRings: loose ring\nMaker: Shires', 'Measure the horse\'s mouth with a bit gauge, or bring the current bit in to compare. Sizes generally run 4.5in to 6in.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Shires Copper Lozenge Snaffle', 'A double-jointed loose ring snaffle with a copper lozenge centre, which encourages a softer, wetter mouth. Stocked in Nairobi.', '2026-10-13 19:56:46', '2026-10-13 19:56:46'),
  ('1893', '95', '12', 'Shires Stainless Steel Snaffle Bit', 'shires-stainless-steel-snaffle-bit', NULL, 'A solid stainless steel snaffle from Shires.', 'A well-made stainless steel snaffle from Shires. Solid stainless takes the wear, does not rust in a damp tack room and cleans up with nothing more than hot water.\n\nCome in and we will help you match the bit to the horse rather than to a catalogue.', 'Material: solid stainless steel\nMaker: Shires\nFinish: polished', 'Measure the horse\'s mouth with a bit gauge, or bring the current bit in to compare.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Shires Stainless Steel Snaffle', 'A solid stainless steel snaffle — the honest starting point for most horses. Bitting advice included at Tack Rack, Nairobi.', '2026-10-13 19:56:46', '2026-10-13 19:56:46'),
  ('1894', '95', NULL, 'Loose Ring Jointed Snaffle', 'loose-ring-jointed-snaffle', NULL, 'A single-jointed loose ring snaffle in stainless steel.', 'The most widely used bit there is: a single-jointed loose ring snaffle in stainless steel. Simple, mild in a quiet hand, and the right starting point for most horses.', 'Material: stainless steel\nMouthpiece: single jointed\nRings: loose ring', 'Measure the horse\'s mouth with a bit gauge, or bring the current bit in to compare.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Loose Ring Jointed Snaffle', 'A single-jointed loose ring snaffle in stainless steel, the standard schooling bit. Sized and advised on at Tack Rack, Ngong Road.', '2026-10-13 19:56:46', '2026-10-13 19:56:46'),
  ('1895', '95', NULL, 'Training Bit with Rope Cheeks', 'training-bit-with-rope-cheeks', NULL, 'A gag-action training bit with rope cheeks and a pulley.', 'A training bit with rope cheeks running through the bit rings, giving a gag action that lifts the head rather than pulling back. Supplied with the cord, pulley and buckles as shown.\n\nA bit like this is a schooling tool, not a shortcut. Please talk to us about whether it is the right answer for your horse before buying.', 'Material: stainless steel rings, corded cheeks\nAction: gag / poll lift\nIncludes: cord, pulley and adjusting buckles', 'Measure the horse\'s mouth with a bit gauge. We would rather discuss the problem with you than sell you the wrong bit.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Training Bit with Rope Cheeks', 'A gag-action training bit with rope cheeks and a pulley, for horses that need a clearer lift. Fitting advice included, Nairobi.', '2026-10-13 19:56:47', '2026-10-13 19:56:47'),
  ('1896', '96', NULL, 'Rubber Bit Guards', 'rubber-bit-guards', NULL, 'Bit guards that stop the bit rubbing at the corners of the mouth.', 'Round guards that sit between the bit ring and the horse\'s cheek, stopping the bit pinching or rubbing at the corners of the mouth. Particularly worth having on a loose ring bit or a young horse still settling into the contact.\n\nSold in pairs, in black and brown.', 'Fitting: sold in pairs\nColours: black, brown\nUse: loose ring and eggbutt bits', 'One size fits standard bit rings.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Rubber Bit Guards', 'Bit guards that stop the bit rubbing at the corners of the mouth — a small part that prevents a lot of soreness. In stock in Nairobi.', '2026-10-13 19:56:47', '2026-10-13 19:56:47'),
  ('1897', '111', NULL, 'Fleece Lined Girth', 'fleece-lined-girth', NULL, 'A girth lined with soft fleece, for horses prone to girth galls.', 'A girth with a soft fleece lining against the horse. The fleece spreads the pressure and stops the rubbing that causes girth galls, which makes it a sensible choice for a thin-skinned horse or one coming back into work.\n\nThe lining comes off and washes.', 'Lining: soft fleece\nBuckles: stainless steel roller\nElastic: both ends\nCare: lining is washable', 'Measure an existing girth from buckle to buckle, or measure the horse from four fingers below the saddle flap on one side to the same point on the other.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Fleece Lined Girth', 'A girth lined with soft fleece for horses prone to girth galls, easy to wash and quick to dry. From Tack Rack, Ngong Road, Nairobi.', '2026-10-13 19:56:47', '2026-10-13 19:56:47'),
  ('1898', '112', NULL, 'Black Elastic Girth', 'black-elastic-girth', NULL, 'A hard-wearing black girth with elastic at both ends.', 'A straightforward black girth with elastic ends, which lets the horse\'s ribcage expand as it works rather than being held rigid. Stainless steel roller buckles make it easy to do up single-handed.', 'Material: hard-wearing webbing\nElastic: both ends\nBuckles: stainless steel roller', 'Measure an existing girth buckle to buckle. Sizes generally run 40in to 54in.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Black Elastic Girth', 'A hard-wearing black girth with elastic at both ends, so the pressure stays even as the horse works. Stocked in Nairobi.', '2026-10-13 19:56:48', '2026-10-13 19:56:48'),
  ('1899', '110', NULL, 'Padded Anti-Chafe Girth', 'padded-anti-chafe-girth', NULL, 'A shaped, padded girth designed to reduce rubbing behind the elbow.', 'A shaped girth with a padded, textured lining that grips without chafing. The curve behind the elbow gives the horse room to move its foreleg freely, which matters a great deal to a horse that jumps.\n\nOne of the more worthwhile upgrades you can make to an otherwise ordinary set of tack.', 'Shape: curved for elbow clearance\nLining: padded, anti-chafe texture\nBuckles: stainless steel roller\nElastic: both ends', 'Measure an existing girth buckle to buckle.', NULL, '0', '0', 'in_stock', NULL, '1', '0', '1', '0', '0', 'Padded Anti-Chafe Girth', 'A shaped, padded girth cut away behind the elbow — the answer for a horse sore in the girth groove. In stock at Tack Rack, Nairobi.', '2026-10-13 19:56:48', '2026-10-13 19:56:48'),
  ('1900', '119', NULL, 'Short Dressage Girth', 'short-dressage-girth', NULL, 'A short girth for dressage saddles with long billets.', 'A short, padded girth for use with a dressage saddle on long billet straps, keeping the buckles clear of the rider\'s leg. Neoprene lined so it grips without slipping.', 'Type: short / dressage girth\nLining: padded neoprene\nBuckles: stainless steel roller', 'Short girths generally run 20in to 34in. Measure an existing girth buckle to buckle.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Short Dressage Girth', 'A short girth for dressage saddles with long billets, keeping the buckles clear of the rider\'s leg. From Tack Rack, Nairobi.', '2026-10-13 19:56:51', '2026-10-13 19:56:51'),
  ('1901', '97', NULL, 'Rubber Guards', 'rubber-guards', NULL, 'Rubber guards that protect the saddle flap from the girth buckles.', 'Flat rubber ovals that slide onto the girth billets and sit between the buckles and the saddle flap. Without them the buckles wear a permanent mark into the underside of the flap — a small item that quietly protects an expensive saddle.\n\nSold in pairs, in black and havana.', 'Material: rubber\nFitting: slides onto the girth billets\nColours: black, havana\nSold: in pairs', 'One size fits standard billet straps.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Rubber Girth Buckle Guards', 'Rubber guards that keep girth buckles from wearing through the saddle flap — a small part that saves an expensive saddle.', '2026-10-13 19:56:51', '2026-10-13 19:56:51'),
  ('1902', '98', '13', 'Korsteel Stainless Steel Stirrup Irons', 'korsteel-stainless-steel-stirrup-irons', NULL, 'Solid stainless steel irons from Korsteel, with a wide tread.', 'Solid stainless steel stirrup irons from Korsteel — heavy enough to hang correctly and find again if you lose one, and hard-wearing enough to last for years.\n\nAlways buy irons that leave roughly a centimetre either side of the boot. Too narrow and the foot jams; too wide and it can slide right through.', 'Material: solid stainless steel\nTread: wide, with a rubber tread pad\nMaker: Korsteel', 'Measured across the inside of the iron. Allow about 1cm clearance either side of your riding boot.', NULL, '0', '0', 'in_stock', NULL, '1', '0', '1', '0', '0', 'Korsteel Stainless Stirrup Irons', 'Solid stainless steel irons with a wide tread, sized for adults and children. Stocked at Tack Rack, Ngong Road, Nairobi.', '2026-10-13 19:56:53', '2026-10-13 19:56:53'),
  ('1903', '98', NULL, 'Peacock Safety Stirrup Irons', 'peacock-safety-stirrup-irons', NULL, 'Safety irons with a rubber release band — the sensible choice for children.', 'Peacock safety irons have a rubber band on the outside instead of a solid branch, so if a rider comes off the band releases and the foot comes free rather than being dragged.\n\nWe would put every child on these, and plenty of adults too.', 'Material: stainless steel with rubber release band\nTread: white rubber tread pad\nUse: recommended for children and novice riders', 'Measured across the inside of the iron. Allow about 1cm clearance either side of the boot.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Peacock Safety Stirrup Irons', 'Safety irons with a rubber release band so the foot comes free in a fall — the sensible choice for children. In stock in Nairobi.', '2026-10-13 19:56:53', '2026-10-13 19:56:53'),
  ('1904', '98', NULL, 'Compositi Lightweight Stirrups', 'compositi-lightweight-stirrups', NULL, 'Light composite stirrups with a wide grippy tread, in several colours.', 'Composite stirrups that weigh a fraction of a steel iron and will not rust. The wide tread is deeply grooved and grips a boot well, which makes a real difference to a rider who struggles to keep their foot still.\n\nAvailable in a range of tread colours.', 'Material: reinforced composite\nTread: wide, deeply grooved\nWeight: considerably lighter than steel\nColours: several tread colours available', 'Measured across the inside of the stirrup. Allow about 1cm clearance either side of the boot.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Compositi Lightweight Stirrups', 'Light composite stirrups with a wide grippy tread, in a choice of colours. Much kinder on the knees than steel. From Tack Rack.', '2026-10-13 19:56:54', '2026-10-13 19:56:54'),
  ('1905', '99', NULL, 'Rubber Stirrup Treads', 'rubber-stirrup-treads', NULL, 'Replacement rubber treads to bring worn irons back to grip.', 'Replacement rubber treads for stainless steel irons. A worn, polished tread is genuinely dangerous in the wet — replacing it costs very little and takes a minute.\n\nAvailable in black and white.', 'Material: ribbed rubber\nColours: black, white\nSold: in pairs\nUse: standard stainless steel irons', 'Match the tread to the width of your irons. Bring one in if you are unsure.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Rubber Stirrup Treads', 'Replacement treads that bring worn stirrup irons back to grip — the cheapest safety upgrade in the tack room. In stock in Nairobi.', '2026-10-13 19:56:54', '2026-10-13 19:56:54'),
  ('1906', '94', NULL, 'Leather Draw Reins', 'leather-draw-reins', NULL, 'Draw reins for schooling, with clips at both ends.', 'Draw reins for schooling work, running from the girth through the bit rings back to the rider\'s hand. Used correctly and briefly they can help a horse find a rounder outline; used badly they teach it to lean.\n\nPlease speak to us, or to your instructor, before schooling in them.', 'Material: leather with clip ends\nFitting: girth to bit ring to hand\nUse: schooling only, not for jumping', 'One length, adjustable.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Leather Draw Reins', 'Leather draw reins with clips at both ends, for schooling a horse into a rounder outline. Advice on correct use included, Nairobi.', '2026-10-13 19:56:57', '2026-10-13 19:56:57'),
  ('1907', '97', NULL, 'Leather Bib Martingale', 'leather-bib-martingale', NULL, 'A bib martingale in brown leather, safer than a standing pair.', 'A bib martingale — a running martingale with a leather bib filling the space between the two straps, so the horse cannot get a foreleg caught through it. Standard for racing and cross country for exactly that reason.\n\nBrown leather with stainless fittings.', 'Material: brown leather\nType: bib (running martingale with filled bib)\nFittings: stainless steel\nIncludes: neck strap', 'Available in pony, cob and full. Adjust so that the rein runs in a straight line from bit to hand when the horse\'s head is at the correct height.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Leather Bib Martingale', 'A brown leather bib martingale — safer than a standing pair for a horse that throws its head. Stocked at Tack Rack, Ngong Road.', '2026-10-13 19:57:00', '2026-10-13 19:57:00'),
  ('1908', '107', NULL, 'Quilted GP Numnah — Red', 'quilted-gp-numnah-red', NULL, 'A shaped, quilted numnah in red, cut for a GP saddle.', 'A shaped numnah cut to follow the line of a general purpose saddle, quilted cotton with a soft lining and girth and billet straps. Washes clean and holds its colour.', 'Shape: general purpose\nFace: quilted cotton\nAttachment: girth and billet straps\nCare: machine washable', 'Available in cob and full. Full fits most horses of 15.2hh and over.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Quilted GP Numnah, Red', 'A shaped, quilted numnah in red, cut for a general purpose saddle and easy to wash. From Tack Rack, Ngong Road, Nairobi.', '2026-10-13 19:57:02', '2026-10-13 19:57:02'),
  ('1909', '107', NULL, 'Quilted GP Numnah — Teal', 'quilted-gp-numnah-teal', NULL, 'The same shaped GP numnah in teal.', 'A shaped GP numnah in teal, quilted cotton with a soft lining. A colour that looks well on a grey or a bay without being loud.', 'Shape: general purpose\nFace: quilted cotton\nAttachment: girth and billet straps\nCare: machine washable', 'Available in cob and full.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Quilted GP Numnah, Teal', 'The same shaped GP numnah in teal — quilted, washable and cut to sit clear of the withers. Stocked at Tack Rack, Nairobi.', '2026-10-13 19:57:06', '2026-10-13 19:57:06'),
  ('1910', '107', NULL, 'Quilted GP Numnah — Black', 'quilted-gp-numnah-black', NULL, 'A shaped GP numnah in black — the one that always looks tidy.', 'A shaped GP numnah in black. It does not show dust or a stray hoof mark the way a white one does, which makes it the pad most people reach for day to day.', 'Shape: general purpose\nFace: quilted cotton\nAttachment: girth and billet straps\nCare: machine washable', 'Available in cob and full.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Quilted GP Numnah, Black', 'A shaped GP numnah in black, the one that always looks tidy however hard the week has been. Washable. In stock in Nairobi.', '2026-10-13 19:57:07', '2026-10-13 19:57:07'),
  ('1911', '107', NULL, 'Quilted GP Numnah — Navy', 'quilted-gp-numnah-navy', NULL, 'A shaped GP numnah in navy.', 'A shaped GP numnah in navy, quilted cotton with a soft lining and girth and billet straps.', 'Shape: general purpose\nFace: quilted cotton\nAttachment: girth and billet straps\nCare: machine washable', 'Available in cob and full.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Quilted GP Numnah, Navy', 'A shaped, quilted GP numnah in navy — smart enough for a lesson and cheap enough to own several. From Tack Rack, Nairobi.', '2026-10-13 19:57:09', '2026-10-13 19:57:09'),
  ('1912', '107', NULL, 'Dressage Square — White', 'dressage-square-white', NULL, 'A crisp white dressage square for the competition ring.', 'A square-cut dressage pad in white — correct turnout for a dressage test and smart enough for a clinic. Quilted cotton with a wicking lining that pulls sweat away from the back.\n\nWashes clean without going grey, which is more than can be said for some.', 'Shape: dressage square\nFace: quilted cotton\nLining: wicking\nAttachment: girth and billet straps\nCare: machine washable', 'Available in cob and full.', NULL, '0', '0', 'in_stock', NULL, '1', '0', '1', '0', '0', 'White Dressage Square', 'A crisp white dressage square cut square to the saddle, for the competition ring. Washes clean and holds its shape. In Nairobi.', '2026-10-13 19:57:12', '2026-10-13 19:57:12'),
  ('1913', '107', NULL, 'Dressage Square — Black', 'dressage-square-black', NULL, 'A square-cut dressage pad in black, for schooling.', 'A square-cut dressage pad in black — the everyday schooling pad, keeping the white one clean for competition day.', 'Shape: dressage square\nFace: quilted cotton\nAttachment: girth and billet straps\nCare: machine washable', 'Available in cob and full.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Black Dressage Square', 'A square-cut dressage pad in black for schooling at home, when white is more trouble than it is worth. From Tack Rack, Nairobi.', '2026-10-13 19:57:14', '2026-10-13 19:57:14'),
  ('1914', '116', '12', 'Ezi-Groom Body Brush', 'ezi-groom-body-brush', NULL, 'A soft body brush with a chunky grip, from the Ezi-Groom range.', 'A soft-bristled body brush on a moulded grip that is genuinely easier to hold than a traditional wooden back — particularly for children and for anyone with cold hands on an early morning.\n\nUsed with a curry comb to lift dust out of the coat and lay it flat.', 'Bristle: soft, for body brushing\nGrip: moulded, easy-hold\nRange: Ezi-Groom by Shires\nCare: rinse and air dry', 'One size.', NULL, '0', '0', 'in_stock', NULL, '1', '0', '1', '0', '0', 'Ezi-Groom Body Brush', 'A soft body brush with a chunky moulded grip — easy to hold with cold or gloved hands. From Shires, stocked in Nairobi.', '2026-10-13 19:57:17', '2026-10-13 19:57:17'),
  ('1915', '117', '12', 'Ezi-Groom Dandy Brush', 'ezi-groom-dandy-brush', NULL, 'A stiff dandy brush for lifting mud and dried sweat.', 'A stiff-bristled dandy brush for getting dried mud and sweat off the coat before you start with the softer brushes. The moulded grip takes the effort out of it.\n\nToo stiff for the face or any clipped area — keep it for the body and legs.', 'Bristle: stiff, for mud and dried sweat\nGrip: moulded, easy-hold\nRange: Ezi-Groom by Shires\nCare: rinse and air dry', 'One size.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Ezi-Groom Dandy Brush', 'A stiff dandy brush for lifting dried mud and sweat, with the Ezi-Groom grip. Stocked at Tack Rack, Ngong Road, Nairobi.', '2026-10-13 19:57:21', '2026-10-13 19:57:21'),
  ('1916', '116', NULL, 'Body Brushes — Colour Range', 'body-brushes-colour-range', NULL, 'Soft body brushes with a moulded grip, in a choice of colours.', 'Soft body brushes with a moulded grip, stocked in a range of colours so every horse on the yard can have its own. Keeping one kit per horse is the simplest way to stop skin conditions moving between animals.', 'Bristle: soft, for body brushing\nGrip: moulded with a hand strap\nColours: several, subject to stock', 'One size.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Body Brushes, Colour Range', 'Soft body brushes with a moulded grip in a choice of colours — one each for a yard full of horses, or a set of your own.', '2026-10-13 19:57:24', '2026-10-13 19:57:24'),
  ('1917', '117', NULL, 'Dandy Brushes — Colour Range', 'dandy-brushes-colour-range', NULL, 'Stiff dandy brushes in a choice of colours.', 'Stiff-bristled dandy brushes for mud and dried sweat, stocked in several colours. A hard-working brush that earns its keep on a wet-season yard.', 'Bristle: stiff\nColours: several, subject to stock', 'One size.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Dandy Brushes, Colour Range', 'Stiff dandy brushes in a choice of colours, for lifting mud before the body brush does the shine. In stock in Nairobi.', '2026-10-13 19:57:25', '2026-10-13 19:57:25'),
  ('1918', '71', NULL, 'Plastic Curry Comb', 'plastic-curry-comb', NULL, 'A plastic curry comb with an adjustable hand strap.', 'A plastic curry comb used in a circular motion to lift dust, loose hair and scurf out of the coat before body brushing. The adjustable strap holds it against the palm so you are not gripping it all the way round the horse.\n\nThe single most useful item in any grooming kit.', 'Material: plastic\nStrap: adjustable hand strap\nUse: circular motion, body only\nCare: rinse clean', 'One size, adjustable strap.', NULL, '0', '0', 'in_stock', NULL, '1', '0', '1', '0', '0', 'Plastic Curry Comb', 'A plastic curry comb with an adjustable hand strap, for lifting loose hair and scurf before body brushing. From Tack Rack, Ngong Road, Nairobi.', '2026-10-13 19:57:27', '2026-10-13 19:57:27'),
  ('1919', '71', NULL, 'Plastic Curry Combs — Colour Range', 'plastic-curry-combs-colour-range', NULL, 'Plastic curry combs with a hand strap, in a choice of colours.', 'The same plastic curry comb with an adjustable hand strap, stocked in a range of colours. Useful for colour-coding a kit per horse on a busy yard.', 'Material: plastic\nStrap: adjustable hand strap\nColours: blue, black, purple, subject to stock', 'One size, adjustable strap.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Plastic Curry Combs, Colours', 'Plastic curry combs with an adjustable strap in blue, black and purple. Buy several and keep one in every grooming kit. In stock.', '2026-10-13 19:57:38', '2026-10-13 19:57:38'),
  ('1920', '71', '12', 'Shires Rubber Curry Comb', 'shires-rubber-curry-comb', NULL, 'An oval rubber curry comb from Shires, with a moulded hand grip.', 'An oval rubber curry comb from Shires, with a moulded grip across the back and three rings of rubber teeth. Used in a circular motion to lift dust, loose hair and scurf out of the coat before body brushing.\n\nShown in blue, and also stocked in black, red and purple.', 'Maker: Shires\nMaterial: rubber\nGrip: moulded handle across the back\nTeeth: three rings\nColours: blue, black, red, purple, subject to stock', 'One size.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Shires Rubber Curry Comb', 'An oval Shires rubber curry comb with a moulded grip and three rings of teeth, in blue, black, red and purple. From Tack Rack, Nairobi.', '2026-10-13 19:57:43', '2026-10-13 19:57:43'),
  ('1921', '118', NULL, 'Mane and Tail Brush', 'mane-and-tail-brush', NULL, 'A cushioned brush for working through mane and tail without breaking hair.', 'A cushioned brush with rounded pins for working through a mane and tail. Start at the bottom and work up, and you will keep far more tail than you will with a comb.\n\nAvailable in several colours.', 'Pins: rounded, cushioned pad\nHandle: moulded grip\nColours: several, subject to stock', 'One size.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Mane and Tail Brush', 'A cushioned brush that works through mane and tail without breaking the hair — worth it if you plait. Stocked in Nairobi.', '2026-10-13 19:57:46', '2026-10-13 19:57:46'),
  ('1922', '72', NULL, 'Stainless Steel Mane Comb', 'stainless-steel-mane-comb', NULL, 'A traditional metal mane comb for pulling and plaiting.', 'A solid stainless steel mane comb for pulling a mane and for sectioning it up when plaiting. Small, cheap and it will outlast almost everything else in the kit.', 'Material: stainless steel\nUse: mane pulling and plaiting', 'One size.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Stainless Steel Mane Comb', 'A traditional metal mane comb for pulling and plaiting, with teeth that will not bend. From Tack Rack, Ngong Road, Nairobi.', '2026-10-13 19:57:49', '2026-10-13 19:57:49'),
  ('1923', '72', '12', 'Ezi-Groom Plaiting Bands', 'ezi-groom-plaiting-bands', NULL, 'Plaiting bands in white and black, sold by the bag.', 'Plaiting bands for manes and tails, sold in generous bags. White for a light mane, black for a dark one — matched properly they disappear completely in the plait.\n\nBuy more than you think you need; they are never where you left them.', 'Colours: white and black\nQuantity: bagged\nRange: Ezi-Groom by Shires', 'One size.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Ezi-Groom Plaiting Bands', 'Plaiting bands in white and black, sold by the bag — buy more than you think you need. From Shires, stocked in Nairobi.', '2026-10-13 19:57:50', '2026-10-13 19:57:50'),
  ('1924', '73', '14', 'HY Grooming and Tack Box', 'hy-grooming-and-tack-box', NULL, 'A sturdy plastic tack box with a lift-out tray and a lockable catch.', 'A hard-wearing plastic grooming and tack box with a metal catch and a lift-out tray inside, so brushes stay on top and the heavier items sit underneath. Stackable, which matters in a crowded tack room.\n\nAvailable in a range of lid colours.', 'Material: hard-wearing moulded plastic\nCatch: metal, lockable\nInterior: lift-out tray\nStackable: yes\nMaker: HY', 'One size. Stackable with others in the range.', NULL, '0', '0', 'in_stock', NULL, '1', '0', '1', '0', '0', 'HY Grooming and Tack Box', 'A sturdy plastic tack box with a lift-out tray and a lockable catch, for keeping a grooming kit together. From Tack Rack, Nairobi.', '2026-10-13 19:57:54', '2026-10-13 19:57:54'),
  ('1925', '74', NULL, 'Beige Riding Breeches', 'beige-riding-breeches', NULL, 'Classic beige breeches with a knee patch — correct for the show ring.', 'Beige breeches cut for riding, with a shaped knee patch and enough stretch to be comfortable through a long schooling session. Beige is correct turnout for showing and most competition, and smart enough to teach in.', 'Colour: beige\nPatch: knee patch\nFabric: stretch riding fabric\nWaist: mid rise', 'Take your usual size. Riding breeches are cut close — if you are between sizes, try both.', NULL, '0', '0', 'in_stock', NULL, '1', '0', '1', '0', '0', 'Beige Riding Breeches', 'Classic beige breeches with a knee patch — the correct colour for the show ring. Sized in person at Tack Rack, Ngong Road.', '2026-10-13 19:57:58', '2026-10-13 19:57:58'),
  ('1926', '74', NULL, 'Navy Riding Breeches', 'navy-riding-breeches', NULL, 'Navy breeches with a contrast panel, for schooling.', 'Navy breeches with a bright contrast panel down the leg — a schooling breech rather than a competition one, and hard-wearing enough for daily use.', 'Colour: navy with contrast panel\nFabric: stretch riding fabric\nWaist: mid rise', 'Take your usual size.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Navy Riding Breeches', 'Navy schooling breeches with a contrast panel, cut to move and easy to wash. Sized in person at Tack Rack, Nairobi.', '2026-10-13 19:57:59', '2026-10-13 19:57:59'),
  ('1927', '74', NULL, 'Black Full Seat Breeches', 'black-full-seat-breeches', NULL, 'Black breeches with a full grip seat, for flatwork.', 'Black breeches with a full grip seat — the patterned panel runs from the knee up through the seat, holding the rider in the saddle without gluing them to it. The choice for dressage and serious flatwork.', 'Colour: black\nSeat: full grip seat\nFabric: four-way stretch\nWaist: mid rise', 'Take your usual size. Full seat breeches are cut close by design.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Black Full Seat Breeches', 'Black breeches with a full grip seat, for riders who want to stay put through flatwork. Sized in person at Tack Rack, Nairobi.', '2026-10-13 19:57:59', '2026-10-13 19:57:59'),
  ('1928', '75', '14', 'HY Leather Jodhpur Boots — Black', 'hy-leather-jodhpur-boots-black', NULL, 'Black leather jodhpur boots with elasticated sides.', 'Leather jodhpur boots in black, with elasticated side gussets and a pull tab so they go on easily. Worn on their own for schooling or under half chaps for longer work.\n\nA proper leather boot will mould to the foot and last; a synthetic one rarely does either.', 'Upper: leather\nSides: elasticated gussets\nSole: rubber, riding heel\nMaker: HY\nColour: black', 'Measure the foot flat, heel to longest toe, late in the day. Between sizes, take the larger.', NULL, '0', '0', 'in_stock', NULL, '1', '0', '1', '0', '0', 'HY Leather Jodhpur Boots, Black', 'Black leather jodhpur boots with elasticated sides, worn alone or under half chaps. Fitted in person at Tack Rack, Nairobi.', '2026-10-13 19:58:00', '2026-10-13 19:58:00'),
  ('1929', '75', '14', 'HY Leather Jodhpur Boots — Brown', 'hy-leather-jodhpur-boots-brown', NULL, 'The same leather jodhpur boot in warm brown.', 'Leather jodhpur boots in brown, with elasticated sides and a pull tab. Brown boots suit brown tack and are the traditional choice for showing and Pony Club.', 'Upper: leather\nSides: elasticated gussets\nSole: rubber, riding heel\nMaker: HY\nColour: brown', 'Measure the foot flat, heel to longest toe, late in the day. Between sizes, take the larger.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'HY Leather Jodhpur Boots, Brown', 'The same leather jodhpur boot in warm brown, with elasticated sides for an easy pull-on. Fitted in person in Nairobi.', '2026-10-13 19:58:00', '2026-10-13 19:58:00'),
  ('1930', '75', NULL, 'Black Half Chaps', 'black-half-chaps', NULL, 'Zip-up half chaps in black, worn over jodhpur boots.', 'Half chaps in black, worn over jodhpur boots to protect the lower leg and give the grip a long boot would. A rear zip with a guard keeps the pull tab clear of the girth.', 'Closure: rear zip with guard\nColour: black\nUse: worn over jodhpur boots', 'Measure the calf at its widest point and from the floor to the back of the knee, wearing your riding boots.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Black Half Chaps', 'Zip-up half chaps in black, worn over jodhpur boots for the look and grip of a long boot at a fraction of the price.', '2026-10-13 19:58:02', '2026-10-13 19:58:02'),
  ('1931', '75', NULL, 'Brown Leather Gaiters', 'brown-leather-gaiters', NULL, 'Leather gaiters in brown, studded, for a smarter turnout.', 'Leather gaiters in brown, fastening with studs rather than a zip. Worn over jodhpur boots they give the clean line of a long boot at a fraction of the cost, and they break in beautifully.', 'Material: leather\nClosure: studs\nColour: brown\nUse: worn over jodhpur boots', 'Measure the calf at its widest point and from the floor to the back of the knee, wearing your riding boots.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Brown Leather Gaiters', 'Studded leather gaiters in brown, for a smarter turnout over jodhpur boots. Fitted to your calf at Tack Rack, Ngong Road.', '2026-10-13 19:58:02', '2026-10-13 19:58:02'),
  ('1932', '76', NULL, 'Competition Number Holder', 'competition-number-holder', NULL, 'A clear armband holder for competition numbers.', 'A clear plastic holder with an elastic strap, worn on the arm to display a competition number. Small, cheap, and the thing everyone forgets until the morning of the show.', 'Material: clear plastic with elastic strap\nWear: on the upper arm\nIncludes: number card where shown', 'One size, elasticated.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Competition Number Holder', 'A clear armband holder that keeps a competition number flat, dry and readable all day. From Tack Rack, Ngong Road, Nairobi.', '2026-10-13 19:58:03', '2026-10-13 19:58:03'),
  ('1933', '76', '15', 'LeMieux Hat Silk', 'lemieux-hat-silk', NULL, 'A navy hat silk with a pom-pom, from LeMieux.', 'A hat silk that pulls over a skull cap to smarten it up and keep the sun off. Navy with a contrast peak and a pom-pom on top.\n\nA silk is also the easiest way to show yard or team colours.', 'Fit: pulls over a standard skull cap\nColour: navy with contrast peak\nDetail: pom-pom\nMaker: LeMieux', 'One size, fits a standard skull cap.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'LeMieux Hat Silk', 'A navy LeMieux hat silk with a pom-pom, cut to sit properly over a skull cap. Stocked at Tack Rack, Ngong Road, Nairobi.', '2026-10-13 19:58:03', '2026-10-13 19:58:03'),
  ('1934', '76', NULL, 'Hat Silk — Red', 'hat-silk-red', NULL, 'A plain red hat silk for a skull cap.', 'A plain red hat silk that pulls over a skull cap. Bright, easy to spot across a cross country course, and a simple way to run yard colours.', 'Fit: pulls over a standard skull cap\nColour: red', 'One size, fits a standard skull cap.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Red Hat Silk', 'A plain red hat silk for a skull cap — the quickest way to smarten a hat or match a team colour. In stock in Nairobi.', '2026-10-13 19:58:06', '2026-10-13 19:58:06'),
  ('1935', '40', NULL, 'Schooling Whip', 'schooling-whip', NULL, 'A long schooling whip, in a smooth or a braided pattern.', 'A long schooling whip, light enough in the hand to be used without disturbing the rein contact, and long enough to reach behind the leg without taking the hand off the rein.\n\nStocked in a smooth navy pattern with a moulded handle, and in a braided pattern with a rubber grip and wrist strap.', 'Type: schooling whip\nShaft: smooth or braided\nHandle: moulded grip, or rubber grip with wrist strap\nColours: navy, black', 'One length. A schooling whip should reach the horse\'s hindquarters with the hand in a normal rein position.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Dressage & Schooling Whips', 'A long schooling whip, smooth or braided, balanced to reach behind the leg without moving the hand. From Tack Rack, Ngong Road, Nairobi.', '2026-10-13 19:58:08', '2026-10-13 19:58:08'),
  ('1936', '40', NULL, 'Lunge Whip', 'lunge-whip', NULL, 'A long lunge whip for groundwork.', 'A long lunge whip for working a horse on a circle. Used to guide and position rather than to chase — the length is there so you can stay at the centre of the circle and still direct the horse.', 'Type: lunge whip\nColour: green\nUse: groundwork and lungeing', 'One length.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Lunge Whip', 'A long lunge whip for groundwork, light enough to hold out for a full session. Stocked at Tack Rack, Ngong Road, Nairobi.', '2026-10-13 19:58:09', '2026-10-13 19:58:09'),
  ('1937', '40', NULL, 'Riding Crop', 'riding-crop', NULL, 'A short jumping crop with a wrist loop.', 'A short riding crop with a broad keeper at the end and a wrist loop on the handle. The length suits jumping and general riding, where a long schooling whip would be in the way.', 'Type: short crop\nHandle: wrist loop\nEnd: broad leather keeper', 'One length.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Riding Crop', 'A short jumping crop with a wrist loop, sized for schooling and the ring. From Tack Rack, Ngong Road, Nairobi.', '2026-10-13 19:58:10', '2026-10-13 19:58:10'),
  ('1938', '108', '16', 'Prolite Saddle Pad', 'prolite-saddle-pad', NULL, 'A shaped black Prolite pad with a spine channel, worn under the saddle.', 'A shaped pad from Prolite, cut to follow the saddle and split down the spine so it stays off the horse\'s back.\n\nBring the saddle in and we will check how the pad changes the fit before you buy.', 'Colour: black\nMaker: Prolite\nShape: saddle-shaped, split spine', NULL, NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Prolite Saddle Pad', 'A shaped black Prolite pad with a split spine channel, worn under the saddle. Bring your saddle and we will check the fit. Tack Rack, Nairobi.', '2026-10-13 19:58:11', '2026-10-13 19:58:11'),
  ('1939', '109', NULL, 'Non-Slip Gel Pad', 'non-slip-gel-pad', NULL, 'A dimpled black gel pad that stops the saddle slipping.', 'A flexible gel pad with a dimpled surface that grips on both sides, used to keep the saddle from sliding and to take some of the jar out of the ride.\n\nIt wipes clean with a damp cloth.', 'Material: gel\nColour: black\nSurface: dimpled, non-slip', NULL, NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Non-Slip Gel Pad', 'A dimpled gel pad that grips on both sides to stop the saddle slipping and take some of the jar out of the ride. Wipes clean. In stock in Nairobi.', '2026-10-13 19:58:12', '2026-10-13 19:58:12'),
  ('1940', '108', NULL, 'Tartan Fleece Rug', 'tartan-fleece-rug', NULL, 'A red, yellow and black tartan fleece rug with front straps.', 'A warm fleece rug in a bold red and yellow tartan, bound in black, with adjustable straps across the chest.\n\nUseful as a cooler after work or as a light layer on a cold Nairobi morning.', 'Material: fleece\nPattern: red, yellow and black tartan\nFastening: chest straps', 'Rugs are measured from the centre of the chest to the point of the buttock. Ask us and we will help you measure.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Tartan Fleece Rug', 'A warm red, yellow and black tartan fleece rug with chest straps — a cooler after work or a light layer on cold mornings. From Tack Rack, Nairobi.', '2026-10-13 19:58:13', '2026-10-13 19:58:13'),
  ('1941', '47', NULL, 'Nylon Headcollar — Colour Range', 'nylon-headcollar-colour-range', NULL, 'An adjustable nylon headcollar with brass fittings, in several colours.', 'A hard-wearing nylon headcollar with brass buckles and rings, adjustable at the headpiece and noseband.\n\nShown here in red, black and royal blue.', 'Material: nylon webbing\nFittings: brass\nColours: red, black, royal blue', 'Sized pony, cob and full. If in doubt, bring the old headcollar in and we will match it.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Nylon Headcollars, Colour Range', 'Adjustable nylon headcollars with brass fittings in red, black and royal blue. Sized pony, cob and full at Tack Rack, Ngong Road, Nairobi.', '2026-10-13 19:58:13', '2026-10-13 19:58:13'),
  ('1942', '47', NULL, 'Lunging Cavesson', 'lunging-cavesson', NULL, 'A padded lunging cavesson, fleece lined at the noseband and headpiece.', 'A lunging cavesson for groundwork, with grey fleece padding over the noseband and headpiece so it does not rub on a horse being worked on a circle.\n\nBrass fittings throughout.', 'Material: nylon webbing, fleece lining\nColour: black with grey fleece\nFittings: brass', 'Sized pony, cob and full.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Lunging Cavesson', 'A lunging cavesson padded with grey fleece at the noseband and headpiece, so it will not rub a horse worked on a circle. In stock in Nairobi.', '2026-10-13 19:58:14', '2026-10-13 19:58:14'),
  ('1943', '47', NULL, 'Rope Lead Ropes', 'rope-lead-ropes', NULL, 'Soft twisted lead ropes with brass trigger clips, in several colours.', 'Thick, soft twisted lead ropes that are comfortable to hold, each finished with a brass trigger clip.\n\nShown here in purple, sky blue and black.', 'Material: twisted rope\nClip: brass trigger clip\nColours: purple, sky blue, black', NULL, NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Rope Lead Ropes', 'Soft, thick twisted lead ropes with brass trigger clips, in purple, sky blue and black. Comfortable to hold. From Tack Rack, Nairobi.', '2026-10-13 19:58:15', '2026-10-13 19:58:15'),
  ('1944', '47', NULL, 'Cotton Lunge Line — Red', 'cotton-lunge-line-red', NULL, 'A long red cotton lunge line with a swivel clip.', 'A flat cotton lunge line in red, soft on the hands and long enough for a proper circle, finished with a swivel clip at one end and a hand loop at the other.', 'Material: cotton webbing\nColour: red\nClip: swivel', NULL, NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Red Cotton Lunge Line', 'A long flat cotton lunge line in red, soft on the hands, with a swivel clip and a hand loop. Stocked at Tack Rack, Ngong Road, Nairobi.', '2026-10-13 19:58:15', '2026-10-13 19:58:15'),
  ('1945', '113', '17', 'Brushing Boots', 'brushing-boots', NULL, 'Brushing boots with a moulded strike guard, in five colours.', 'Brushing boots with a moulded outer shell over a soft lining, to protect the inside of the leg from knocks by the opposite hoof.\n\nThree touch-close straps keep them secure.', 'Colours: black, grey, green, navy, red\nFastening: three touch-close straps\nSizes: pony, cob, full', 'Sold by leg size. Tell us the horse’s height and build and we will find the right pair.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Brushing Boots, Five Colours', 'Brushing boots with a moulded strike guard and three touch-close straps, protecting the inside of the leg. In stock in Nairobi.', '2026-10-13 19:58:16', '2026-10-13 19:58:16'),
  ('1946', '113', '17', 'Anatomic Brushing Boots', 'anatomic-brushing-boots', NULL, 'Black brushing boots with red straps and a moulded shell.', 'Anatomic brushing boots with a moulded shell on the inside of the leg and wide red touch-close straps.\n\nA soft neoprene-style body keeps them close to the leg without rubbing.', 'Range: Anatomic\nColour: black with red straps\nFastening: two touch-close straps', 'Sold by leg size. Tell us the horse’s height and build and we will find the right pair.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Anatomic Brushing Boots', 'Anatomic brushing boots with a moulded shell and wide red straps, close to the leg without rubbing. From Tack Rack, Nairobi.', '2026-10-13 19:58:16', '2026-10-13 19:58:16'),
  ('1947', '114', '12', 'Rubber Overreach Boots', 'rubber-overreach-boots', NULL, 'Black ribbed rubber overreach boots with a touch-close fastening.', 'Ribbed rubber overreach boots that sit over the hoof to protect the heel and coronet from a hind foot catching them.\n\nThe touch-close fastening means they go on without being pulled over the foot.', 'Maker: Shires\nMaterial: rubber\nColour: black\nFastening: touch-close\nSizes: pony, cob, full', 'Sized by hoof. Bring the horse’s shoe size or measure around the pastern.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Shires Rubber Overreach Boots', 'Ribbed rubber overreach boots from Shires with a touch-close fastening, protecting heels and coronets from the hind feet. Stocked in Nairobi.', '2026-10-13 19:58:17', '2026-10-13 19:58:17'),
  ('1948', '114', '17', 'Neoprene Overreach Boots', 'neoprene-overreach-boots', NULL, 'Soft neoprene overreach boots, lighter and quieter than rubber.', 'Soft overreach boots with a red strike panel, lighter and quieter than rubber, protecting the heel and coronet from the hind feet.', 'Material: neoprene\nColours: black, blue, green, red\nFastening: touch-close\nSizes: pony, cob, full', 'Sized by hoof. Bring the horse’s shoe size or measure around the pastern.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Neoprene Overreach Boots', 'Soft neoprene overreach boots — lighter and quieter than rubber, protecting the heel and coronet. In stock at Tack Rack, Nairobi.', '2026-10-13 19:58:17', '2026-10-13 19:58:17'),
  ('1949', '115', NULL, 'Cohesive Bandages', 'cohesive-bandages', NULL, 'Self-adhesive cohesive bandages in blue and purple.', 'Cohesive bandage sticks to itself but not to hair, so it holds a dressing or a tail in place without pins or tape.\n\nTears by hand. Shown in blue and purple.', 'Type: self-adhesive cohesive bandage\nColours: blue, purple', NULL, NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Cohesive Bandages', 'Self-adhesive cohesive bandage in blue and purple — sticks to itself, not to hair, and tears by hand. For the first aid box. From Tack Rack.', '2026-10-13 19:58:18', '2026-10-13 19:58:18'),
  ('1950', '115', NULL, 'Quilted Bandage Pads', 'quilted-bandage-pads', NULL, 'White quilted pads to wear under stable and travel bandages.', 'Quilted pads that go under a stable or travel bandage, spreading the pressure evenly down the leg.\n\nSold as a set.', 'Colour: white\nConstruction: quilted', NULL, NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Quilted Bandage Pads', 'White quilted pads for under stable and travel bandages, spreading the pressure evenly down the leg. Sold as a set at Tack Rack, Nairobi.', '2026-10-13 19:58:20', '2026-10-13 19:58:20'),
  ('1951', '48', NULL, 'Rubber Sausage Boot', 'rubber-sausage-boot', NULL, 'A padded rubber ring worn at the pastern to prevent capped elbows.', 'A sausage boot, or shoe boil ring, is buckled round the pastern of a horse that lies down with a foot tucked under the elbow, keeping the heel of the shoe off the elbow.', 'Material: rubber\nColour: black\nFastening: strap through the split', NULL, NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Rubber Sausage Boot', 'A padded rubber shoe boil ring buckled round the pastern, keeping the shoe off the elbow of a horse that lies tucked up. In stock in Nairobi.', '2026-10-13 19:58:20', '2026-10-13 19:58:20'),
  ('1952', '55', '19', 'Robinson Veterinary Gamgee', 'robinson-veterinary-gamgee', NULL, 'A roll of veterinary gamgee for padding bandages and dressings.', 'Absorbent cotton wool wrapped in gauze, used under bandages for support and protection and over wound dressings.\n\nCut to the length you need.', 'Maker: Robinson\nType: veterinary gamgee roll', NULL, NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Robinson Veterinary Gamgee', 'A roll of Robinson veterinary gamgee — absorbent cotton wool in gauze, for padding bandages and covering dressings. From Tack Rack, Nairobi.', '2026-10-13 19:58:20', '2026-10-13 19:58:20'),
  ('1953', '62', '20', 'Davis Hoof Treatment Boot', 'davis-hoof-treatment-boot', NULL, 'A rigid treatment boot for soaking or protecting a poulticed hoof.', 'A rigid plastic boot from Davis, made in the USA, that holds a soak or a poultice against the hoof and keeps it clean while it works.\n\nAn adjustable strap fastens it at the pastern.', 'Maker: Davis (USA)\nMaterial: rigid plastic\nFastening: adjustable strap', 'Sized by hoof. Bring the horse’s shoe size.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Davis Hoof Treatment Boot', 'A rigid Davis treatment boot, made in the USA, that holds a soak or poultice on the hoof and keeps it clean. Stocked at Tack Rack, Nairobi.', '2026-10-13 19:58:22', '2026-10-13 19:58:22'),
  ('1954', '62', '17', 'Medi-Boot', 'medi-boot', NULL, 'A tough fabric poultice boot that holds a dressing on the hoof.', 'A hard-wearing fabric boot that draws closed around the pastern, holding a poultice or dressing on the hoof and keeping it clean.', 'Material: heavy-duty fabric\nColour: black', 'Sized by hoof. Bring the horse’s shoe size.', NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Medi-Boot Poultice Boot', 'A tough fabric Medi-Boot that draws closed at the pastern, holding a poultice or dressing on the hoof. In stock at Tack Rack, Nairobi.', '2026-10-13 19:58:23', '2026-10-13 19:58:23'),
  ('1955', '59', NULL, 'Hoof Oil', 'hoof-oil', NULL, 'Hoof oil distributed by Tack Rack, in two bottle sizes.', 'Hoof oil brushed on to the wall and sole to help keep the hoof in good condition and looking smart.\n\nDistributed by Tack Rack from our shop on Ngong Road.', 'Distributed by: Tack Rack Ltd\nSizes: two bottle sizes', NULL, NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Hoof Oil', 'Hoof oil brushed on to the wall and sole to keep hooves in good condition and looking smart. Distributed by Tack Rack, in two bottle sizes.', '2026-10-13 19:58:24', '2026-10-13 19:58:24'),
  ('1956', '59', NULL, 'Stockholm Tar', 'stockholm-tar', NULL, 'Stockholm tar for the hoof, distributed by Tack Rack, in two sizes.', 'A traditional hoof preparation, labelled here as a corrective hoof supplement for horses.\n\nDistributed by Tack Rack.', 'Distributed by: Tack Rack Ltd\nSizes: two bottle sizes', NULL, NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Stockholm Tar for Hooves', 'Traditional Stockholm tar for the hoof, distributed by Tack Rack in two bottle sizes. From our shop off Ngong Road, Nairobi.', '2026-10-13 19:58:26', '2026-10-13 19:58:26'),
