  ('2035', '58', NULL, 'Feed Scoop — Colour Range', 'feed-scoop-colour-range', NULL, 'A round plastic feed scoop with a long handle, in several colours.', 'A deep round feed scoop with a long, easy-grip handle.\n\nShown in black, green, purple, orange and red — one colour per horse keeps the feeds straight.', 'Material: plastic\nColours: black, green, purple, orange, red', NULL, NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Feed Scoops, Colour Range', 'Deep round feed scoops with a long easy-grip handle in black, green, purple, orange and red — one colour per horse. From Tack Rack, Nairobi.', '2026-10-13 20:00:08', '2026-10-13 20:00:08'),
  ('2036', '58', NULL, 'Rope Haynet — Yellow', 'rope-haynet-yellow', NULL, 'A knotted rope haynet in yellow.', 'A knotted rope haynet in yellow, with a drawstring top for tying up.', 'Material: knotted rope\nColour: yellow', NULL, NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Yellow Rope Haynet', 'A knotted rope haynet in yellow with a drawstring top for tying up. In stock at Tack Rack, Ngong Road, Nairobi.', '2026-10-13 20:00:10', '2026-10-13 20:00:10'),
  ('2037', '58', NULL, 'Flexible Tub — Orange', 'flexible-tub-orange', NULL, 'A deep, flexible plastic tub with two handles.', 'A deep, flexible plastic tub with two carry handles — for water, feed or carrying kit round the yard. It will not crack if it is trodden on.', 'Material: flexible plastic\nColour: orange\nHandles: two', NULL, NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Orange Flexible Tub', 'A deep, flexible plastic tub with two handles for water, feed or carrying kit — it will not crack if trodden on. From Tack Rack, Nairobi.', '2026-10-13 20:00:11', '2026-10-13 20:00:11'),
  ('2038', '58', NULL, 'Shallow Feed Tub — Green', 'shallow-feed-tub-green', NULL, 'A shallow, flexible feed tub with two handles.', 'A shallow, flexible feed tub with two handles, low enough for a horse to eat from on the ground.', 'Material: flexible plastic\nColour: green\nHandles: two', NULL, NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Green Shallow Feed Tub', 'A shallow, flexible feed tub with two handles, low enough for a horse to eat from on the ground. In stock at Tack Rack, Nairobi.', '2026-10-13 20:00:12', '2026-10-13 20:00:12'),
  ('2039', '58', '44', 'Hydrophane Cribox', 'hydrophane-cribox', NULL, 'A paste that prevents crib-biting, in two sizes.', 'Cribox from Hydrophane prevents crib-biting.\n\nAvailable in 450g and 225g tubs.', 'Maker: Hydrophane\nSizes: 450g, 225g', NULL, NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Hydrophane Cribox', 'Cribox from Hydrophane prevents crib-biting. Available in 450g and 225g tubs at Tack Rack, Ngong Road, Nairobi.', '2026-10-13 20:00:13', '2026-10-13 20:00:13'),
  ('2040', '57', '32', 'Leather Dressing', 'leather-dressing', NULL, 'Moore’s Quality leather dressing that softens and preserves, 1 litre.', 'Leather dressing from Moore\'s Quality that softens and preserves leather. Directions are on the label.', 'Maker: Moore’s Quality\nSize: 1 litre', NULL, NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Moore’s Leather Dressing', 'Moore’s Quality leather dressing that softens and preserves leather, in a 1 litre can. Stocked at Tack Rack, Ngong Road, Nairobi.', '2026-10-13 20:00:15', '2026-10-13 20:00:15'),
  ('2041', '57', '32', 'Glycerine Leather & Saddle Soap', 'glycerine-leather-saddle-soap', NULL, 'A bar of Moore’s Quality glycerine leather and saddle soap.', 'A bar of glycerine leather and saddle soap from Moore\'s Quality, for everyday cleaning of saddles and bridles.', 'Maker: Moore’s Quality\nForm: bar', NULL, NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Moore’s Glycerine Saddle Soap', 'A bar of Moore’s Quality glycerine leather and saddle soap for everyday cleaning of saddles and bridles. From Tack Rack, Nairobi.', '2026-10-13 20:00:16', '2026-10-13 20:00:16'),
  ('2042', '57', '32', 'Dubbin', 'dubbin', NULL, 'Moore’s Quality dubbin, 500ml.', 'Dubbin from Moore\'s Quality for leather.', 'Maker: Moore’s Quality\nSize: 500ml', NULL, NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Moore’s Dubbin', 'Moore’s Quality dubbin for leather, in a 500ml tub. In stock at Tack Rack, Ngong Road, Nairobi.', '2026-10-13 20:00:17', '2026-10-13 20:00:17'),
  ('2043', '57', '32', 'Leather Soap', 'leather-soap', NULL, 'Moore’s Quality leather soap, 500ml.', 'Leather soap from Moore\'s Quality, in a 500ml tub.', 'Maker: Moore’s Quality\nSize: 500ml', NULL, NULL, '0', '0', 'in_stock', NULL, '0', '0', '1', '0', '0', 'Moore’s Leather Soap', 'Moore’s Quality leather soap in a 500ml tub, for cleaning saddles, bridles and boots. Stocked at Tack Rack, Ngong Road, Nairobi.', '2026-10-13 20:00:19', '2026-10-13 20:00:19');
